insert into questions (topic_id, subtopic_id, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty, question_type, ao_weighting, generation_batch_id, content_hash, active, created_at)
select s.topic_id, s.id, v.qt, v.a, v.b, v.c, v.d, v.co, v.ex, v.dif, v.qtype, v.ao, '16300e7d-a5e3-4b3b-9ca1-4865408672f4'::uuid, encode(sha256(convert_to(lower(btrim(regexp_replace(v.qt, '\s+', ' ', 'g'))), 'UTF8')), 'hex'), true, now() + v.n * interval '1 microsecond'
from (values
  (1, 'Atoms, elements, compounds and mixtures', 'Which of these substances is a compound?', 'Oxygen', 'Air', 'Copper', 'Carbon dioxide', 'D', 'A compound contains two or more elements chemically combined in fixed proportions. Oxygen and copper are elements; air is a mixture.', 'foundation', 'recall', 'AO1'),
  (2, 'Atoms, elements, compounds and mixtures', 'Which technique is best for obtaining pure water from salt solution?', 'Crystallisation', 'Paper chromatography', 'Simple distillation', 'Filtration', 'C', 'Distillation evaporates the water and condenses it, leaving the salt behind. Crystallisation recovers the salt, not the water.', 'foundation', 'applied', 'AO2'),
  (3, 'Atoms, elements, compounds and mixtures', 'Ethanol (boiling point 78 °C) and water (boiling point 100 °C) are mixed. Which method is most suitable for separating them?', 'Fractional distillation', 'Simple distillation', 'Filtration', 'Paper chromatography', 'A', 'Fractional distillation separates miscible liquids with close boiling points; the fractionating column gives a much better separation than simple distillation.', 'higher', 'applied', 'AO2'),
  (4, 'Development of the model of the atom', 'What did Rutherford''s alpha particle scattering experiment show?', 'The nucleus contains neutrons', 'Electrons orbit the nucleus at specific distances', 'The mass of an atom is concentrated in a small, positively charged nucleus', 'Atoms are tiny solid spheres that cannot be divided', 'C', 'A few alpha particles were deflected through large angles, which could only happen if the positive charge and mass were concentrated in a tiny nucleus. Bohr later proposed electron shells and Chadwick found neutrons.', 'foundation', 'recall', 'AO1'),
  (5, 'Development of the model of the atom', 'In the alpha scattering experiment, most alpha particles passed straight through the gold foil. What did this suggest?', 'The nucleus is negatively charged', 'Alpha particles have no charge', 'Gold atoms are smaller than alpha particles', 'Most of the atom is empty space', 'D', 'If most particles pass through undeflected, they met nothing in their path, so most of the atom must be empty space.', 'foundation', 'applied', 'AO3'),
  (6, 'Development of the model of the atom', 'Whose experimental work provided evidence that the nucleus contains neutrons?', 'Niels Bohr', 'Ernest Rutherford', 'J.J. Thomson', 'James Chadwick', 'D', 'Chadwick showed the existence of neutrons about 20 years after the nuclear model was accepted. Thomson discovered the electron and Bohr proposed electron shells.', 'foundation', 'recall', 'AO1'),
  (7, 'Subatomic particles, isotopes and relative atomic mass', 'An atom of fluorine has atomic number 9 and mass number 19. How many neutrons does it have?', '9', '10', '28', '19', 'B', 'Neutrons = mass number − atomic number = 19 − 9 = 10.', 'foundation', 'calculation', 'AO2'),
  (8, 'Subatomic particles, isotopes and relative atomic mass', 'Chlorine is 75% chlorine-35 and 25% chlorine-37. What is its relative atomic mass?', '35.5', '72.0', '36.0', '35.0', 'A', 'Relative atomic mass = (75 × 35 + 25 × 37) ÷ 100 = 35.5. It is closer to 35 because chlorine-35 is more abundant.', 'foundation', 'calculation', 'AO2'),
  (9, 'Subatomic particles, isotopes and relative atomic mass', 'Which statement about isotopes of the same element is correct?', 'They have the same mass number', 'They have the same number of protons but different numbers of neutrons', 'Their neutral atoms have different numbers of electrons', 'They have the same number of neutrons but different numbers of protons', 'B', 'Isotopes are atoms of the same element (same proton number) with different numbers of neutrons, so their mass numbers differ.', 'foundation', 'recall', 'AO1'),
  (10, 'Electronic structure', 'What is the electronic structure of sodium (atomic number 11)?', '2,8,1', '2,8,2', '2,9', '8,2,1', 'A', 'The first shell holds 2 electrons and the second holds 8, so the 11th electron goes into the third shell: 2,8,1.', 'foundation', 'recall', 'AO1'),
  (11, 'Electronic structure', 'An element has the electronic structure 2,8,6. Which group of the periodic table is it in?', 'Group 6', 'Group 3', 'Group 8', 'Group 2', 'A', 'The group number equals the number of electrons in the outer shell, which is 6. (This element is sulfur.)', 'foundation', 'applied', 'AO2'),
  (12, 'Electronic structure', 'Which element has the electronic structure 2,8,8,2?', 'Calcium', 'Argon', 'Magnesium', 'Potassium', 'A', '2 + 8 + 8 + 2 = 20 electrons, so the atomic number is 20: calcium. Magnesium is 2,8,2 and potassium is 2,8,8,1.', 'foundation', 'applied', 'AO2'),
  (13, 'The periodic table, metals and non-metals', 'Why do elements in the same group of the periodic table have similar chemical properties?', 'They have the same mass number', 'They have the same number of neutrons', 'They have the same number of electrons in their outer shell', 'They have the same number of electron shells', 'C', 'Chemical reactions involve outer-shell electrons, so elements with the same number of outer electrons react in similar ways. Elements in the same period have the same number of shells.', 'foundation', 'recall', 'AO1'),
  (14, 'The periodic table, metals and non-metals', 'Why did Mendeleev leave gaps in his periodic table?', 'For elements that were too reactive to study', 'Because he ordered the elements strictly by atomic weight', 'For elements that had not yet been discovered', 'Because he ran out of space in each row', 'C', 'Mendeleev left gaps so that elements with similar properties lined up in groups, and predicted the properties of the missing elements. He sometimes changed the order of atomic weights to do this.', 'foundation', 'recall', 'AO1'),
  (15, 'The periodic table, metals and non-metals', 'Where are metals found in the periodic table?', 'Only in Group 0', 'Mostly to the right and towards the top', 'Mostly to the left and towards the bottom', 'Only in Group 7', 'C', 'Metals are on the left and towards the bottom; non-metals are towards the top right.', 'foundation', 'recall', 'AO1'),
  (16, 'Group 0, Group 1 and Group 7', 'Why are the noble gases unreactive?', 'Their atoms are very small', 'They have a stable arrangement of electrons, with a full outer shell', 'They are all gases at room temperature', 'They have no electrons', 'B', 'Noble gas atoms do not need to gain, lose or share electrons because their outer shells are already full.', 'foundation', 'recall', 'AO1'),
  (17, 'Group 0, Group 1 and Group 7', 'Why does reactivity increase going down Group 1?', 'The nucleus has fewer protons', 'The outer electron is further from the nucleus, so it is lost more easily', 'The number of outer electrons increases', 'The atoms gain electrons more easily', 'B', 'Going down the group the atoms get bigger, so the single outer electron is further from the nucleus and less strongly attracted, and is lost more easily.', 'higher', 'applied', 'AO3'),
  (18, 'Group 0, Group 1 and Group 7', 'Chlorine water is added to potassium bromide solution. What happens?', 'Chlorine is displaced from the solution', 'Bromine is displaced, because chlorine is more reactive than bromine', 'There is no reaction, because bromine is more reactive than chlorine', 'Potassium is displaced as a metal', 'B', 'A more reactive halogen displaces a less reactive one from its salt. Reactivity decreases down Group 7, so chlorine displaces bromine and the solution turns orange.', 'foundation', 'applied', 'AO2'),
  (19, 'Properties of transition metals', 'Compared with Group 1 metals, transition metals typically have…', 'higher melting points and higher densities', 'lower melting points and lower densities', 'only one possible charge on their ions', 'a more vigorous reaction with cold water', 'A', 'Transition metals such as iron are hard, dense and have high melting points, and are much less reactive than Group 1 metals. They often form ions with different charges.', 'foundation', 'recall', 'AO1'),
  (20, 'Properties of transition metals', 'Which of these is a typical property of transition metal compounds?', 'They always form ions with a 1+ charge', 'They are often coloured', 'They react vigorously with cold water', 'They are always white', 'B', 'Many transition metal compounds are coloured, e.g. copper(II) sulfate is blue. Transition metals form ions with different charges, e.g. Fe²⁺ and Fe³⁺.', 'foundation', 'recall', 'AO1')
) as v(n, sub, qt, a, b, c, d, co, ex, dif, qtype, ao)
join subtopics s on s.topic_id = (select id from topics where subject_id = (select id from subjects where name = 'Chemistry') and name = 'Atomic Structure and the Periodic Table') and s.name = v.sub
