insert into questions (topic_id, subtopic_id, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty, question_type, ao_weighting, generation_batch_id, content_hash, active, created_at)
select s.topic_id, s.id, v.qt, v.a, v.b, v.c, v.d, v.co, v.ex, v.dif, v.qtype, v.ao, '16300e7d-a5e3-4b3b-9ca1-4865408672f4'::uuid, encode(sha256(convert_to(lower(btrim(regexp_replace(v.qt, '\s+', ' ', 'g'))), 'UTF8')), 'hex'), true, now() + v.n * interval '1 microsecond'
from (values
  (1, 'Ionic, covalent and metallic bonding', 'What type of bonding is found in sodium chloride?', 'Ionic', 'Metallic', 'Hydrogen', 'Covalent', 'A', 'Sodium chloride forms from a metal and a non-metal, so electrons are transferred to form Na⁺ and Cl⁻ ions held by ionic bonds.', 'foundation', 'recall', 'AO1'),
  (2, 'Ionic, covalent and metallic bonding', 'When magnesium reacts with oxygen to form magnesium oxide, what happens to the electrons?', 'Magnesium and oxygen atoms share a pair of electrons', 'Each magnesium atom transfers one electron to an oxygen atom', 'Each magnesium atom transfers two electrons to an oxygen atom', 'Each oxygen atom transfers two electrons to a magnesium atom', 'C', 'Magnesium (Group 2) loses its two outer electrons to form Mg²⁺; oxygen (Group 6) gains two to form O²⁻.', 'foundation', 'applied', 'AO2'),
  (3, 'Ionic, covalent and metallic bonding', 'What is a covalent bond?', 'The attraction between positive ions and delocalised electrons', 'The transfer of electrons from a metal to a non-metal', 'A shared pair of electrons between two atoms', 'The attraction between oppositely charged ions', 'C', 'Covalent bonds form between non-metal atoms that share pairs of electrons. The other options describe ionic and metallic bonding.', 'foundation', 'recall', 'AO1'),
  (4, 'Ionic, covalent and metallic bonding', 'Aluminium forms Al³⁺ ions and oxygen forms O²⁻ ions. What is the formula of aluminium oxide?', 'AlO₃', 'Al₃O₂', 'Al₂O₃', 'AlO', 'C', 'The charges must balance: 2 × (+3) = +6 and 3 × (−2) = −6, so the formula is Al₂O₃.', 'foundation', 'applied', 'AO2'),
  (5, 'States of matter and properties of ionic compounds', 'Why does sodium chloride have a high melting point?', 'Strong covalent bonds must be broken', 'Delocalised electrons hold the lattice together', 'A lot of energy is needed to overcome the strong electrostatic forces between oppositely charged ions', 'The intermolecular forces are strong', 'C', 'Sodium chloride is a giant ionic lattice. Strong electrostatic attractions act in all directions between the ions, so melting it needs a lot of energy.', 'foundation', 'recall', 'AO1'),
  (6, 'States of matter and properties of ionic compounds', 'Why do ionic compounds conduct electricity when molten but not when solid?', 'When molten, the electrons become delocalised', 'When solid, there are no ions present', 'When molten, the ions are free to move and carry charge', 'When molten, covalent bonds break to release electrons', 'C', 'In the solid the ions are fixed in the lattice. When it melts or dissolves the ions can move, so charge can flow.', 'foundation', 'applied', 'AO2'),
  (7, 'States of matter and properties of ionic compounds', 'In a chemical equation, what does the state symbol (aq) mean?', 'Liquid', 'Solid', 'Gas', 'Dissolved in water', 'D', '(aq) stands for aqueous, meaning dissolved in water. The other state symbols are (s), (l) and (g).', 'foundation', 'recall', 'AO1'),
  (8, 'States of matter and properties of ionic compounds', 'A substance melts at −7 °C and boils at 59 °C. What state is it in at 25 °C?', 'Solid', 'Liquid', 'Gas', 'It cannot be predicted', 'B', '25 °C is above the melting point but below the boiling point, so the substance is a liquid.', 'foundation', 'applied', 'AO2'),
  (9, 'Small molecules, polymers and giant covalent structures', 'Why do substances made of small molecules, such as methane, have low boiling points?', 'The molecules have no bonds', 'The covalent bonds in the molecules are weak', 'Their ions are only weakly attracted', 'Only weak intermolecular forces need to be overcome', 'D', 'Boiling separates molecules from each other, which only overcomes the weak forces between molecules. The strong covalent bonds inside the molecules are not broken.', 'foundation', 'recall', 'AO1'),
  (10, 'Small molecules, polymers and giant covalent structures', 'Why is poly(ethene) a solid at room temperature when ethene is a gas?', 'It has delocalised electrons', 'Its covalent bonds are weaker', 'It contains ionic bonds', 'Its molecules are much larger, so the intermolecular forces between them are stronger', 'D', 'Polymer molecules are very large, and intermolecular forces get stronger as molecules get bigger, so more energy is needed to separate them.', 'higher', 'applied', 'AO3'),
  (11, 'Small molecules, polymers and giant covalent structures', 'Which substance has a giant covalent structure?', 'Silicon dioxide', 'Sodium chloride', 'Carbon dioxide', 'Methane', 'A', 'Silicon dioxide (silica) is a giant covalent lattice. Carbon dioxide and methane are small molecules, and sodium chloride is ionic.', 'foundation', 'recall', 'AO1'),
  (12, 'Properties of metals and alloys', 'Why can pure metals be bent and shaped?', 'The delocalised electrons are fixed in place', 'There are no forces between the atoms', 'The layers of atoms can slide over each other', 'The atoms share pairs of electrons', 'C', 'In a pure metal all the atoms are the same size and arranged in regular layers, which can slide over one another.', 'foundation', 'recall', 'AO1'),
  (13, 'Properties of metals and alloys', 'Why are alloys harder than pure metals?', 'The atoms in an alloy are all the same size', 'Atoms of different sizes distort the layers, so they cannot slide over each other as easily', 'Alloys have no delocalised electrons', 'Alloys contain covalent bonds', 'B', 'The different-sized atoms in an alloy disrupt the regular layers, making it harder for the layers to slide.', 'foundation', 'recall', 'AO1'),
  (14, 'Properties of metals and alloys', 'Why are metals good conductors of electricity?', 'Their positive ions move through the structure', 'They contain free-moving negative ions', 'Their atoms share pairs of electrons', 'Their delocalised electrons can move through the structure', 'D', 'Metallic bonding involves a sea of delocalised electrons that are free to move and carry charge (and thermal energy).', 'foundation', 'recall', 'AO1'),
  (15, 'Diamond, graphite, graphene and fullerenes', 'Why can graphite conduct electricity?', 'It contains ions that can move', 'Its layers are held together by strong covalent bonds', 'Each carbon atom bonds to four others', 'Each carbon atom bonds to three others, leaving one delocalised electron per atom', 'D', 'In graphite each carbon forms three covalent bonds, so one electron per atom is delocalised and can move along the layers.', 'foundation', 'recall', 'AO1'),
  (16, 'Diamond, graphite, graphene and fullerenes', 'Why is diamond very hard?', 'It has delocalised electrons', 'It is made of layers that slide over each other', 'It has strong intermolecular forces between small molecules', 'Each carbon atom forms four strong covalent bonds in a giant structure', 'D', 'Diamond is a rigid giant covalent structure where every carbon is bonded to four others, so a lot of energy is needed to break it.', 'foundation', 'recall', 'AO1'),
  (17, 'Diamond, graphite, graphene and fullerenes', 'What is graphene?', 'A single layer of graphite', 'A cylindrical carbon nanotube', 'A hollow cage-shaped molecule of carbon atoms', 'A form of carbon where each atom bonds to four others', 'A', 'Graphene is one layer of graphite, one atom thick. Hollow cages are fullerenes such as buckminsterfullerene, and cylinders are nanotubes.', 'foundation', 'recall', 'AO1'),
  (18, 'Nanoparticles', 'What is the size range of nanoparticles?', '1–100 µm', '1–100 nm', '100–2500 nm', '0.1–1 nm', 'B', 'Nanoparticles are 1–100 nm across. Fine particles (PM2.5) are 100–2500 nm.', 'foundation', 'recall', 'AO1'),
  (19, 'Nanoparticles', 'A cube with sides of 10 nm is compared with a cube with sides of 1 nm. By what factor is the surface area to volume ratio of the smaller cube bigger?', '1000', '10', '1', '100', 'B', 'For a cube, surface area ÷ volume = 6 ÷ side length. 6/1 = 6 and 6/10 = 0.6, so the ratio is 10 times bigger. When side length falls by 10, the ratio rises by 10.', 'higher', 'calculation', 'AO2'),
  (20, 'Nanoparticles', 'Why can a smaller mass of a catalyst in nanoparticle form be as effective as a larger mass of the normal catalyst?', 'Nanoparticles are made of different atoms', 'Nanoparticles have a lower density', 'Nanoparticles have more ionic bonds', 'Nanoparticles have a much higher surface area to volume ratio', 'D', 'More of the catalyst''s atoms are on the surface where reactions happen, so less catalyst is needed.', 'foundation', 'applied', 'AO2')
) as v(n, sub, qt, a, b, c, d, co, ex, dif, qtype, ao)
join subtopics s on s.topic_id = (select id from topics where subject_id = (select id from subjects where name = 'Chemistry') and name = 'Bonding, Structure and Properties') and s.name = v.sub
where not exists (select 1 from questions q where encode(sha256(convert_to(lower(btrim(regexp_replace(q.question_text, '\s+', ' ', 'g'))), 'UTF8')), 'hex') = encode(sha256(convert_to(lower(btrim(regexp_replace(v.qt, '\s+', ' ', 'g'))), 'UTF8')), 'hex'));

