select s.topic_id, s.id, v.qt, v.a, v.b, v.c, v.d, v.co, v.ex, v.dif, v.qtype, v.ao, '16300e7d-a5e3-4b3b-9ca1-4865408672f4'::uuid, encode(sha256(convert_to(lower(btrim(regexp_replace(v.qt, '\s+', ' ', 'g'))), 'UTF8')), 'hex'), true, now() + v.n * interval '1 microsecond'
from (values
  (1, 'Conservation of mass, relative formula mass and balanced equations', 'Calculate the relative formula mass (Mr) of CaCO₃. (Ar: Ca = 40, C = 12, O = 16)', '84', '116', '100', '68', 'C', 'Mr = 40 + 12 + (3 × 16) = 100. 68 comes from using only one oxygen.', 'foundation', 'calculation', 'AO2'),
  (2, 'Conservation of mass, relative formula mass and balanced equations', 'When magnesium ribbon is heated in air, the mass of solid increases. Why?', 'Oxygen from the air combines with the magnesium', 'The magnesium absorbs heat energy, which adds mass', 'The magnesium expands when it is hot', 'Mass is created in the reaction', 'A', 'Mass is conserved. The magnesium oxide formed includes the mass of oxygen atoms taken from the air, so the solid gets heavier.', 'foundation', 'applied', 'AO3'),
  (3, 'Conservation of mass, relative formula mass and balanced equations', 'Which equation is correctly balanced?', '2H₂ + O₂ → 2H₂O', 'H₂ + O₂ → H₂O', 'H₂ + O₂ → 2H₂O', '2H₂ + 2O₂ → 2H₂O', 'A', 'In 2H₂ + O₂ → 2H₂O there are 4 H and 2 O atoms on each side.', 'foundation', 'applied', 'AO2'),
  (4, 'Conservation of mass, relative formula mass and balanced equations', 'When calcium carbonate is heated in an open tube, the mass of solid decreases. What is the best explanation?', 'Carbon dioxide gas is produced and escapes', 'Oxygen from the air is absorbed', 'Mass is destroyed in the reaction', 'Calcium evaporates', 'A', 'CaCO₃ → CaO + CO₂. Total mass is conserved, but the carbon dioxide gas escapes from the open tube, so the solid weighs less.', 'foundation', 'applied', 'AO3'),
  (5, 'Moles, reacting masses and limiting reactants', 'How many moles are there in 22 g of carbon dioxide (Mr = 44)?', '968', '22', '2', '0.5', 'D', 'Moles = mass ÷ Mr = 22 ÷ 44 = 0.5 mol.', 'foundation', 'calculation', 'AO2'),
  (6, 'Moles, reacting masses and limiting reactants', 'What is the value of the Avogadro constant?', '1.66 × 10²³ per mole', '6.02 × 10²³ per mole', '3.00 × 10⁸ per mole', '6.02 × 10⁻²³ per mole', 'B', 'One mole of any substance contains 6.02 × 10²³ particles (atoms, molecules or ions).', 'foundation', 'recall', 'AO1'),
  (7, 'Moles, reacting masses and limiting reactants', '2Mg + O₂ → 2MgO. What mass of magnesium oxide forms from 48 g of magnesium? (Ar: Mg = 24, O = 16)', '160 g', '80 g', '64 g', '40 g', 'B', '48 ÷ 24 = 2 mol Mg, which makes 2 mol MgO. Mr of MgO = 40, so the mass is 2 × 40 = 80 g.', 'foundation', 'calculation', 'AO2'),
  (8, 'Moles, reacting masses and limiting reactants', '4 g of hydrogen reacts with 64 g of oxygen: 2H₂ + O₂ → 2H₂O. Which reactant is limiting, and what mass of water forms? (Ar: H = 1, O = 16)', 'Hydrogen is limiting; 68 g of water', 'Oxygen is limiting; 72 g of water', 'Oxygen is limiting; 36 g of water', 'Hydrogen is limiting; 36 g of water', 'D', '4 g H₂ = 2 mol and 64 g O₂ = 2 mol. 2 mol H₂ only needs 1 mol O₂, so hydrogen runs out first. It makes 2 mol H₂O = 2 × 18 = 36 g; the rest of the oxygen is in excess.', 'higher', 'calculation', 'AO3'),
  (9, 'Yield and atom economy', 'A reaction has a theoretical yield of 50 g, but only 40 g of product is obtained. What is the percentage yield?', '90%', '40%', '80%', '125%', 'C', 'Percentage yield = actual ÷ theoretical × 100 = 40 ÷ 50 × 100 = 80%.', 'foundation', 'calculation', 'AO2'),
  (10, 'Yield and atom economy', 'Which of these is a reason why the percentage yield of a reaction may be less than 100%?', 'A catalyst was used', 'Some of the product is lost when it is separated from the reaction mixture', 'The products were dried before weighing', 'The reactants were weighed accurately', 'B', 'Yields are reduced by product lost during separation, reversible reactions that don''t go to completion, and unexpected side reactions.', 'foundation', 'recall', 'AO1'),
  (11, 'Yield and atom economy', 'Calculate the atom economy for making hydrogen in Zn + 2HCl → ZnCl₂ + H₂. (Mr: Zn = 65, HCl = 36.5, ZnCl₂ = 136, H₂ = 2)', '50%', '1.45%', '98.6%', '2.9%', 'B', 'Atom economy = Mr of desired product ÷ total Mr of reactants × 100 = 2 ÷ (65 + 2 × 36.5) × 100 = 2 ÷ 138 × 100 = 1.45%.', 'higher', 'calculation', 'AO2'),
  (12, 'Yield and atom economy', 'Why is a high atom economy important for sustainable development?', 'The reaction always happens faster', 'Fewer resources are wasted as unwanted products', 'No energy is needed for the reaction', 'The percentage yield is always 100%', 'B', 'High atom economy means more of the reactant atoms end up in the useful product, so less is wasted. It says nothing about rate or yield.', 'foundation', 'recall', 'AO1'),
  (13, 'Concentrations of solutions and titration calculations', '25 g of salt is dissolved in water to make 500 cm³ of solution. What is the concentration in g/dm³?', '12.5 g/dm³', '0.05 g/dm³', '20 g/dm³', '50 g/dm³', 'D', '500 cm³ = 0.5 dm³. Concentration = 25 ÷ 0.5 = 50 g/dm³.', 'foundation', 'calculation', 'AO2'),
  (14, 'Concentrations of solutions and titration calculations', 'A solution contains 0.2 mol of solute in 250 cm³. What is its concentration in mol/dm³?', '50 mol/dm³', '1.25 mol/dm³', '0.05 mol/dm³', '0.8 mol/dm³', 'D', '250 cm³ = 0.25 dm³. Concentration = 0.2 ÷ 0.25 = 0.8 mol/dm³.', 'higher', 'calculation', 'AO2'),
  (15, 'Concentrations of solutions and titration calculations', '25.0 cm³ of sodium hydroxide solution is neutralised by 20.0 cm³ of 0.10 mol/dm³ hydrochloric acid. NaOH + HCl → NaCl + H₂O. What is the concentration of the sodium hydroxide?', '0.10 mol/dm³', '0.0020 mol/dm³', '0.080 mol/dm³', '0.125 mol/dm³', 'C', 'Moles HCl = 0.10 × 0.0200 = 0.0020 mol, which reacts 1:1 with NaOH. Concentration NaOH = 0.0020 ÷ 0.0250 = 0.080 mol/dm³.', 'higher', 'calculation', 'AO2'),
  (16, 'Concentrations of solutions and titration calculations', 'In a titration, which piece of apparatus is used to add the acid gradually to the alkali until the end point?', 'A pipette', 'A burette', 'A gas syringe', 'A measuring cylinder', 'B', 'The burette adds acid in small, measured amounts, drop by drop near the end point. A pipette measures a fixed volume of alkali into the flask.', 'foundation', 'recall', 'AO1'),
  (17, 'Volumes of gases', 'At room temperature and pressure, what volume does 1 mole of any gas occupy?', '22.4 cm³', '24 cm³', '24 dm³', '1 dm³', 'C', 'At room temperature and pressure (20 °C, 1 atm), one mole of any gas occupies 24 dm³ (24 000 cm³).', 'foundation', 'recall', 'AO1'),
  (18, 'Volumes of gases', 'What volume does 0.25 mol of oxygen gas occupy at room temperature and pressure?', '24 dm³', '0.01 dm³', '96 dm³', '6 dm³', 'D', 'Volume = moles × 24 dm³ = 0.25 × 24 = 6 dm³.', 'foundation', 'calculation', 'AO2'),
  (19, 'Volumes of gases', '10 g of calcium carbonate (Mr = 100) fully decomposes: CaCO₃ → CaO + CO₂. What volume of carbon dioxide is produced at room temperature and pressure?', '24 dm³', '0.24 dm³', '2.4 dm³', '240 dm³', 'C', '10 ÷ 100 = 0.1 mol CaCO₃, giving 0.1 mol CO₂. Volume = 0.1 × 24 = 2.4 dm³.', 'higher', 'calculation', 'AO2'),
  (20, 'Volumes of gases', '2CO + O₂ → 2CO₂. What volume of oxygen reacts exactly with 40 cm³ of carbon monoxide at the same temperature and pressure?', '80 cm³', '40 cm³', '20 cm³', '10 cm³', 'C', 'Equal volumes of gases contain equal numbers of moles, so volumes react in the ratio of the equation: 2 : 1. 40 cm³ CO needs 20 cm³ O₂.', 'higher', 'calculation', 'AO3')
) as v(n, sub, qt, a, b, c, d, co, ex, dif, qtype, ao)
join subtopics s on s.topic_id = (select id from topics where subject_id = (select id from subjects where name = 'Chemistry') and name = 'Quantitative Chemistry') and s.name = v.sub
where not exists (select 1 from questions q where encode(sha256(convert_to(lower(btrim(regexp_replace(q.question_text, '\s+', ' ', 'g'))), 'UTF8')), 'hex') = encode(sha256(convert_to(lower(btrim(regexp_replace(v.qt, '\s+', ' ', 'g'))), 'UTF8')), 'hex'));

insert into quizzes (topic_id, title, display_order, question_count, cooldown_hours) values ((select id from topics where subject_id = (select id from subjects where name = 'Chemistry') and name = 'Quantitative Chemistry'), 'Quiz 1', 1, 0, 168);
with ordered as (
  select q.id, row_number() over (order by q.created_at) - 1 as i
  from questions q join subtopics s on s.id = q.subtopic_id
  where q.generation_batch_id = '16300e7d-a5e3-4b3b-9ca1-4865408672f4'::uuid and q.topic_id = (select id from topics where subject_id = (select id from subjects where name = 'Chemistry') and name = 'Quantitative Chemistry')
)
