insert into subtopics (topic_id, name, spec_ref, display_order) values ((select id from topics where subject_id = (select id from subjects where name = 'Chemistry') and name = 'Chemical Changes'), 'Reactions of acids, salts and neutralisation', '4.4.2.1-4.4.2.3', 2);
insert into subtopics (topic_id, name, spec_ref, display_order) values ((select id from topics where subject_id = (select id from subjects where name = 'Chemistry') and name = 'Chemical Changes'), 'pH, strong and weak acids, and titrations', '4.4.2.4-4.4.2.6', 3);
insert into subtopics (topic_id, name, spec_ref, display_order) values ((select id from topics where subject_id = (select id from subjects where name = 'Chemistry') and name = 'Chemical Changes'), 'Electrolysis', '4.4.3', 4);

insert into questions (topic_id, subtopic_id, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty, question_type, ao_weighting, generation_batch_id, content_hash, active, created_at)
select s.topic_id, s.id, v.qt, v.a, v.b, v.c, v.d, v.co, v.ex, v.dif, v.qtype, v.ao, '16300e7d-a5e3-4b3b-9ca1-4865408672f4'::uuid, encode(sha256(convert_to(lower(btrim(regexp_replace(v.qt, '\s+', ' ', 'g'))), 'UTF8')), 'hex'), true, now() + v.n * interval '1 microsecond'
from (values
  (1, 'Reactivity series, extraction of metals, oxidation and reduction', 'Which metal can be extracted from its oxide by reduction with carbon?', 'Aluminium', 'Iron', 'Magnesium', 'Potassium', 'B', 'Carbon can only reduce oxides of metals less reactive than carbon. Iron is below carbon in the reactivity series; the others are above it.', 'foundation', 'recall', 'AO1'),
  (2, 'Reactivity series, extraction of metals, oxidation and reduction', 'Why is aluminium extracted by electrolysis rather than by heating its oxide with carbon?', 'Aluminium is less reactive than carbon', 'Carbon reacts with aluminium to form a compound', 'Aluminium is more reactive than carbon', 'Aluminium oxide has a low melting point', 'C', 'Carbon cannot remove oxygen from the oxide of a metal more reactive than itself, so electrolysis must be used.', 'foundation', 'applied', 'AO2'),
  (3, 'Reactivity series, extraction of metals, oxidation and reduction', 'In terms of oxygen, what is reduction?', 'Loss of electrons', 'Gain of oxygen', 'Gain of hydrogen ions', 'Loss of oxygen', 'D', 'Reduction is the loss of oxygen (or gain of electrons); oxidation is the gain of oxygen (or loss of electrons).', 'foundation', 'recall', 'AO1'),
  (4, 'Reactivity series, extraction of metals, oxidation and reduction', 'In the reaction Fe + CuSO₄ → FeSO₄ + Cu, which species is oxidised?', 'Sulfate ions, which lose electrons', 'Copper ions, which gain electrons', 'Iron atoms, which lose electrons', 'Iron atoms, which gain electrons', 'C', 'Fe → Fe²⁺ + 2e⁻: iron loses electrons, so it is oxidised (OIL RIG). Copper ions gain electrons and are reduced; sulfate is a spectator ion.', 'higher', 'applied', 'AO3'),
  (5, 'Reactivity series, extraction of metals, oxidation and reduction', 'Which of these metals does not react with dilute hydrochloric acid?', 'Zinc', 'Copper', 'Magnesium', 'Iron', 'B', 'Copper is below hydrogen in the reactivity series, so it cannot displace hydrogen from acids.', 'foundation', 'recall', 'AO1'),
  (6, 'Reactions of acids, salts and neutralisation', 'Which salt is formed when zinc oxide reacts with sulfuric acid?', 'Zinc nitrate', 'Zinc sulfide', 'Zinc sulfate', 'Zinc chloride', 'C', 'Sulfuric acid makes sulfates, hydrochloric acid makes chlorides and nitric acid makes nitrates.', 'foundation', 'applied', 'AO2'),
  (7, 'Reactions of acids, salts and neutralisation', 'Which gas is produced when a metal carbonate reacts with an acid?', 'Carbon monoxide', 'Oxygen', 'Hydrogen', 'Carbon dioxide', 'D', 'Acid + metal carbonate → salt + water + carbon dioxide. Hydrogen is produced when an acid reacts with a metal.', 'foundation', 'recall', 'AO1'),
  (8, 'Reactions of acids, salts and neutralisation', 'When making copper sulfate crystals from copper oxide and sulfuric acid, why is excess copper oxide added?', 'To produce hydrogen gas', 'To speed up crystallisation', 'To make sure all the acid reacts', 'To make the crystals larger', 'C', 'Adding the insoluble base in excess uses up all the acid; the leftover copper oxide is then filtered off before crystallisation.', 'foundation', 'applied', 'AO2'),
  (9, 'Reactions of acids, salts and neutralisation', 'Which ionic equation represents the neutralisation of an acid by an alkali?', 'H⁺(aq) + OH⁻(aq) → H₂O(l)', '2H₂(g) + O₂(g) → 2H₂O(l)', 'OH⁻(aq) → O²⁻(aq) + H⁺(aq)', 'Na⁺(aq) + Cl⁻(aq) → NaCl(s)', 'A', 'In every acid–alkali neutralisation, hydrogen ions from the acid react with hydroxide ions from the alkali to form water.', 'foundation', 'recall', 'AO1'),
  (10, 'Reactions of acids, salts and neutralisation', 'Magnesium reacts with hydrochloric acid. What are the products?', 'Magnesium oxide and hydrogen', 'Magnesium chloride and hydrogen', 'Magnesium chloride and water', 'Magnesium chloride, water and carbon dioxide', 'B', 'Metal + acid → salt + hydrogen. Water is produced with bases, and carbon dioxide with carbonates.', 'foundation', 'recall', 'AO1'),
  (11, 'pH, strong and weak acids, and titrations', 'A solution has a pH of 3. What is it?', 'Acidic', 'Alkaline', 'Neutral', 'Strongly alkaline', 'A', 'Solutions below pH 7 are acidic, pH 7 is neutral and above pH 7 is alkaline.', 'foundation', 'recall', 'AO1'),
  (12, 'pH, strong and weak acids, and titrations', 'What is meant by a strong acid?', 'An acid that is completely ionised in aqueous solution', 'An acid that is only partially ionised in solution', 'An acid with a pH of exactly 7', 'An acid with a high concentration', 'A', 'Strength is about how completely the acid ionises; concentration is about how much acid is dissolved in a given volume.', 'foundation', 'recall', 'AO1'),
  (13, 'pH, strong and weak acids, and titrations', 'The hydrogen ion concentration of a solution is increased by a factor of 100. How does the pH change?', 'It decreases by 1', 'It decreases by 100', 'It increases by 2', 'It decreases by 2', 'D', 'Each decrease of 1 pH unit is a 10× increase in H⁺ concentration. 100 = 10 × 10, so the pH falls by 2.', 'higher', 'applied', 'AO3'),
  (14, 'pH, strong and weak acids, and titrations', 'Ethanoic acid and hydrochloric acid of the same concentration are compared. Why does the ethanoic acid have a higher pH?', 'Hydrochloric acid releases hydroxide ions', 'Ethanoic acid is a weak acid, so it is only partially ionised', 'Ethanoic acid is completely ionised', 'Ethanoic acid is more dilute', 'B', 'At the same concentration, a weak acid releases fewer H⁺ ions because it is only partially ionised, so its pH is higher.', 'higher', 'applied', 'AO3'),
  (15, 'pH, strong and weak acids, and titrations', 'Which indicator is suitable for an acid–alkali titration?', 'Limewater', 'Red litmus paper', 'Universal indicator', 'Phenolphthalein', 'D', 'A titration needs a single indicator with a sharp colour change at the end point, such as phenolphthalein or methyl orange. Universal indicator changes gradually through many colours.', 'foundation', 'applied', 'AO2'),
  (16, 'Electrolysis', 'In electrolysis, what is the electrolyte?', 'A solid metal that conducts electricity', 'A covalent liquid such as ethanol', 'An ionic compound that is molten or dissolved in water', 'The positive electrode', 'C', 'The electrolyte must contain ions that are free to move, so the ionic compound must be melted or dissolved.', 'foundation', 'recall', 'AO1'),
  (17, 'Electrolysis', 'What is produced at the cathode (negative electrode) when molten lead bromide is electrolysed?', 'Hydrogen', 'Lead', 'Bromine', 'Oxygen', 'B', 'Positive Pb²⁺ ions are attracted to the cathode and gain electrons to form lead. Bromine forms at the anode. There is no water, so no hydrogen or oxygen.', 'foundation', 'applied', 'AO2'),
  (18, 'Electrolysis', 'When sodium chloride solution is electrolysed, which product forms at the cathode?', 'Hydrogen', 'Oxygen', 'Sodium', 'Chlorine', 'A', 'In solution, hydrogen is produced at the cathode because sodium is more reactive than hydrogen. Chlorine forms at the anode.', 'foundation', 'applied', 'AO2'),
  (19, 'Electrolysis', 'In the extraction of aluminium, why is aluminium oxide mixed with cryolite?', 'To make the aluminium purer', 'To raise the melting point', 'To stop the carbon anodes from burning', 'To lower the melting point, reducing energy costs', 'D', 'Aluminium oxide melts above 2000 °C. Dissolving it in molten cryolite lets electrolysis happen at a much lower temperature, saving energy.', 'foundation', 'recall', 'AO1'),
  (20, 'Electrolysis', 'Which half equation shows what happens at the anode when chloride ions are discharged?', '2Cl⁻ → Cl₂ + 2e⁻', 'Cl₂ + 2e⁻ → 2Cl⁻', '2Cl⁻ + 2e⁻ → Cl₂', 'Cl⁻ + e⁻ → Cl', 'A', 'At the anode, negative ions lose electrons (oxidation). Two chloride ions each lose one electron and form a chlorine molecule.', 'higher', 'recall', 'AO1')
) as v(n, sub, qt, a, b, c, d, co, ex, dif, qtype, ao)
join subtopics s on s.topic_id = (select id from topics where subject_id = (select id from subjects where name = 'Chemistry') and name = 'Chemical Changes') and s.name = v.sub
where not exists (select 1 from questions q where encode(sha256(convert_to(lower(btrim(regexp_replace(q.question_text, '\s+', ' ', 'g'))), 'UTF8')), 'hex') = encode(sha256(convert_to(lower(btrim(regexp_replace(v.qt, '\s+', ' ', 'g'))), 'UTF8')), 'hex'));

