select z.id, o.id, (o.i / 1)::int + 1
from ordered o join quizzes z on z.topic_id = (select id from topics where subject_id = (select id from subjects where name = 'Chemistry') and name = 'Chemical Changes') and z.title = 'Quiz ' || ((o.i % 1) + 1);
update quizzes z set question_count = (select count(*) from quiz_questions qq where qq.quiz_id = z.id) where z.topic_id = (select id from topics where subject_id = (select id from subjects where name = 'Chemistry') and name = 'Chemical Changes');

insert into topics (subject_id, name, spec_ref, paper, display_order) values ((select id from subjects where name = 'Chemistry'), 'Energy Changes', 'C5', 'Paper 1', 5);
insert into subtopics (topic_id, name, spec_ref, display_order) values ((select id from topics where subject_id = (select id from subjects where name = 'Chemistry') and name = 'Energy Changes'), 'Exothermic and endothermic reactions and reaction profiles', '4.5.1.1-4.5.1.2', 1);
insert into subtopics (topic_id, name, spec_ref, display_order) values ((select id from topics where subject_id = (select id from subjects where name = 'Chemistry') and name = 'Energy Changes'), 'Bond energies', '4.5.1.3', 2);
insert into subtopics (topic_id, name, spec_ref, display_order) values ((select id from topics where subject_id = (select id from subjects where name = 'Chemistry') and name = 'Energy Changes'), 'Chemical cells and fuel cells', '4.5.2', 3);

insert into questions (topic_id, subtopic_id, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty, question_type, ao_weighting, generation_batch_id, content_hash, active, created_at)
select s.topic_id, s.id, v.qt, v.a, v.b, v.c, v.d, v.co, v.ex, v.dif, v.qtype, v.ao, '16300e7d-a5e3-4b3b-9ca1-4865408672f4'::uuid, encode(sha256(convert_to(lower(btrim(regexp_replace(v.qt, '\s+', ' ', 'g'))), 'UTF8')), 'hex'), true, now() + v.n * interval '1 microsecond'
from (values
  (1, 'Exothermic and endothermic reactions and reaction profiles', 'During an exothermic reaction, what happens to the temperature of the surroundings?', 'It stays the same', 'It increases', 'It always falls below 0 °C', 'It decreases', 'B', 'Exothermic reactions transfer energy to the surroundings, so the temperature of the surroundings rises.', 'foundation', 'recall', 'AO1'),
  (2, 'Exothermic and endothermic reactions and reaction profiles', 'Which of these is an endothermic process?', 'Respiration', 'Neutralisation', 'Thermal decomposition', 'Combustion', 'C', 'Thermal decomposition takes in energy from the surroundings. Combustion, neutralisation and respiration all release energy.', 'foundation', 'recall', 'AO1'),
  (3, 'Exothermic and endothermic reactions and reaction profiles', 'What is the activation energy of a reaction?', 'The total energy of the products', 'The energy stored in the reactants', 'The minimum energy that particles need to react when they collide', 'The energy released by the reaction', 'C', 'Particles must collide with at least the activation energy to react. On a reaction profile it is the rise from the reactants to the peak.', 'foundation', 'recall', 'AO1'),
  (4, 'Exothermic and endothermic reactions and reaction profiles', 'On a reaction profile for an endothermic reaction, where are the products?', 'Higher in energy than the reactants', 'At the same energy as the reactants', 'At the peak of the curve', 'Lower in energy than the reactants', 'A', 'Endothermic reactions take in energy overall, so the products end up at a higher energy level than the reactants.', 'foundation', 'applied', 'AO2'),
  (5, 'Exothermic and endothermic reactions and reaction profiles', 'Which everyday product uses an endothermic reaction?', 'Cold packs for sports injuries', 'Self-heating cans', 'Hand warmers', 'Camping stoves', 'A', 'Cold packs take in energy from the surroundings and feel cold. Hand warmers, self-heating cans and burning fuel are exothermic.', 'foundation', 'applied', 'AO2'),
  (6, 'Exothermic and endothermic reactions and reaction profiles', 'A student mixes two solutions and the temperature falls from 21 °C to 15 °C. What can be concluded?', 'The reaction is endothermic', 'No reaction took place', 'The reaction is exothermic', 'The reaction released 6 J of energy', 'A', 'A fall in temperature means energy was taken in from the surroundings, so the reaction is endothermic.', 'foundation', 'applied', 'AO3'),
  (7, 'Exothermic and endothermic reactions and reaction profiles', 'In a temperature change practical, why is the reaction done in a polystyrene cup with a lid?', 'To speed up the reaction', 'To stop the acid reacting with the cup', 'To reduce energy transfer to the surroundings', 'To add energy so the temperature rise is larger', 'C', 'Polystyrene is a good thermal insulator and the lid reduces heat lost, so the measured temperature change is more accurate.', 'foundation', 'applied', 'AO2'),
  (8, 'Bond energies', 'In terms of bonds, why is a reaction exothermic overall?', 'More energy is released forming new bonds than is needed to break existing bonds', 'No bonds are broken during the reaction', 'More energy is needed to break bonds than is released forming bonds', 'Breaking bonds releases energy', 'A', 'Breaking bonds takes in energy and making bonds releases it. If more is released than taken in, the reaction is exothermic overall.', 'foundation', 'recall', 'AO1'),
  (9, 'Bond energies', 'Is breaking chemical bonds endothermic or exothermic?', 'Neither, because there is no energy change', 'Exothermic, because energy must be supplied', 'Exothermic, because energy is released', 'Endothermic, because energy must be supplied', 'D', 'Energy is always needed to break bonds, so bond breaking is endothermic. Bond making is exothermic.', 'foundation', 'recall', 'AO1'),
  (10, 'Bond energies', 'H₂ + Cl₂ → 2HCl. Bond energies (kJ/mol): H–H = 436, Cl–Cl = 242, H–Cl = 431. What is the overall energy change?', '+247 kJ/mol', '−247 kJ/mol', '+184 kJ/mol', '−184 kJ/mol', 'D', 'Bonds broken = 436 + 242 = 678. Bonds made = 2 × 431 = 862. Energy change = 678 − 862 = −184 kJ/mol. Forgetting the 2 in 2HCl gives 247.', 'higher', 'calculation', 'AO2'),
  (11, 'Bond energies', 'In a reaction, 2000 kJ/mol is needed to break bonds and 2400 kJ/mol is released when new bonds form. What is the overall energy change?', '+400 kJ/mol', '−400 kJ/mol', '−4400 kJ/mol', '+4400 kJ/mol', 'B', 'Energy change = energy to break bonds − energy released making bonds = 2000 − 2400 = −400 kJ/mol (exothermic).', 'foundation', 'calculation', 'AO2'),
  (12, 'Bond energies', 'CH₄ + 2O₂ → CO₂ + 2H₂O. How many O–H bonds are formed when one molecule of methane burns?', '8', '1', '2', '4', 'D', 'Each water molecule has two O–H bonds, and two water molecules are made, so 2 × 2 = 4 O–H bonds form.', 'foundation', 'applied', 'AO2'),
  (13, 'Bond energies', 'Bond energies (kJ/mol): C–H = 413, O=O = 498, C=O = 805, O–H = 464. What is the energy change for CH₄ + 2O₂ → CO₂ + 2H₂O?', '−1052 kJ/mol', '−320 kJ/mol', '+818 kJ/mol', '−818 kJ/mol', 'D', 'Broken: 4 × 413 + 2 × 498 = 2648. Made: 2 × 805 + 4 × 464 = 3466. Change = 2648 − 3466 = −818 kJ/mol.', 'higher', 'calculation', 'AO2'),
  (14, 'Bond energies', 'The overall energy change for a reaction is +92 kJ/mol. What does this tell you?', 'The activation energy is 92 kJ/mol', 'The reaction is endothermic: more energy is needed to break bonds than is released making them', 'The reaction is exothermic', 'The products have 92 kJ/mol less energy than the reactants', 'B', 'A positive energy change means energy is taken in overall, so the reaction is endothermic and the products have more energy than the reactants.', 'foundation', 'applied', 'AO3'),
  (15, 'Chemical cells and fuel cells', 'What is a simple chemical cell made from?', 'Two non-metals with no electrolyte', 'Two different metals in contact with an electrolyte', 'A single metal surrounded by a gas', 'Two identical metals in distilled water', 'B', 'A cell needs two different metals (electrodes) and an electrolyte. The voltage depends on the metals and the electrolyte.', 'foundation', 'recall', 'AO1'),
  (16, 'Chemical cells and fuel cells', 'Which pair of metals in a simple cell would give the largest voltage?', 'Magnesium and copper', 'Zinc and magnesium', 'Iron and copper', 'Zinc and iron', 'A', 'The bigger the difference in reactivity between the two metals, the bigger the voltage. Magnesium is the most reactive and copper the least reactive of these.', 'foundation', 'applied', 'AO2'),
  (17, 'Chemical cells and fuel cells', 'Why do non-rechargeable cells, such as alkaline batteries, eventually stop producing a voltage?', 'One of the reactants is used up', 'The electrons run out of the wires', 'The electrolyte turns into a metal', 'The metals become more reactive', 'A', 'The chemical reactions stop when one of the reactants has been used up. Non-rechargeable cells cannot reverse the reaction.', 'foundation', 'recall', 'AO1'),
  (18, 'Chemical cells and fuel cells', 'What is the only product of the overall reaction in a hydrogen fuel cell?', 'Water', 'Hydrogen peroxide', 'Water and carbon dioxide', 'Carbon dioxide', 'A', 'In a hydrogen fuel cell, hydrogen is oxidised to produce water: 2H₂ + O₂ → 2H₂O. No carbon dioxide is made.', 'foundation', 'recall', 'AO1'),
  (19, 'Chemical cells and fuel cells', 'Which is a disadvantage of hydrogen fuel cells compared with rechargeable batteries?', 'They produce carbon dioxide', 'They release toxic metal compounds when disposed of', 'They have to be recharged from mains electricity', 'Hydrogen is a flammable gas that is difficult to store', 'D', 'Hydrogen is stored as a gas under pressure and is flammable. Batteries, not fuel cells, contain toxic chemicals and need recharging.', 'foundation', 'applied', 'AO3'),
  (20, 'Chemical cells and fuel cells', 'In a hydrogen fuel cell, which half equation shows the reaction at the negative electrode?', '2H₂ → 4H⁺ + 4e⁻', '2H₂ + 4e⁻ → 4H⁺', 'O₂ → 2O²⁻ + 4e⁻', 'O₂ + 4H⁺ + 4e⁻ → 2H₂O', 'A', 'Hydrogen is oxidised (loses electrons) at the negative electrode. Oxygen is reduced at the positive electrode: O₂ + 4H⁺ + 4e⁻ → 2H₂O.', 'higher', 'recall', 'AO1')
) as v(n, sub, qt, a, b, c, d, co, ex, dif, qtype, ao)
join subtopics s on s.topic_id = (select id from topics where subject_id = (select id from subjects where name = 'Chemistry') and name = 'Energy Changes') and s.name = v.sub
where not exists (select 1 from questions q where encode(sha256(convert_to(lower(btrim(regexp_replace(q.question_text, '\s+', ' ', 'g'))), 'UTF8')), 'hex') = encode(sha256(convert_to(lower(btrim(regexp_replace(v.qt, '\s+', ' ', 'g'))), 'UTF8')), 'hex'));

insert into quizzes (topic_id, title, display_order, question_count, cooldown_hours) values ((select id from topics where subject_id = (select id from subjects where name = 'Chemistry') and name = 'Energy Changes'), 'Quiz 1', 1, 0, 168);
with ordered as (
  select q.id, row_number() over (order by q.created_at) - 1 as i
  from questions q join subtopics s on s.id = q.subtopic_id
  where q.generation_batch_id = '16300e7d-a5e3-4b3b-9ca1-4865408672f4'::uuid and q.topic_id = (select id from topics where subject_id = (select id from subjects where name = 'Chemistry') and name = 'Energy Changes')
)
insert into quiz_questions (quiz_id, question_id, position)
select z.id, o.id, (o.i / 1)::int + 1
from ordered o join quizzes z on z.topic_id = (select id from topics where subject_id = (select id from subjects where name = 'Chemistry') and name = 'Energy Changes') and z.title = 'Quiz ' || ((o.i % 1) + 1);
update quizzes z set question_count = (select count(*) from quiz_questions qq where qq.quiz_id = z.id) where z.topic_id = (select id from topics where subject_id = (select id from subjects where name = 'Chemistry') and name = 'Energy Changes');

